/* Capture each argument once before exposing it and invoking the policy. */
#define MAC_HOOK_NARG_( _0, _1, _2, _3, _4, _5, _6, _7, _8, n, ...) n
#define MAC_HOOK_NARG(...) \
	MAC_HOOK_NARG_(_, ##__VA_ARGS__, 8, 7, 6, 5, 4, 3, 2, 1, 0)
#define MAC_HOOK_INVOKE(kind, hook, policy, ...) \
	__CONCAT(MAC_HOOK_INVOKE_, MAC_HOOK_NARG(__VA_ARGS__)) \
	    (kind, hook, policy, ##__VA_ARGS__)

#define MAC_HOOK_INVOKE_0(kind, hook, policy) \
	__extension__ ({ \
		SDT_PROBE2(mac_framework, , , hook__start, \
		    __XSTRING(hook), (policy)->mpc_name); \
		__CONCAT(MAC_HOOK_ARGS_, hook)(policy); \
		MAC_HOOK_RESULT_ ## kind(hook, policy); \
	})

#define MAC_HOOK_INVOKE_1(kind, hook, policy, a0) \
	__extension__ ({ \
		__auto_type __mac_arg0 = (a0); \
		SDT_PROBE2(mac_framework, , , hook__start, \
		    __XSTRING(hook), (policy)->mpc_name); \
		__CONCAT(MAC_HOOK_ARGS_, hook)(policy, __mac_arg0); \
		MAC_HOOK_RESULT_ ## kind(hook, policy, __mac_arg0); \
	})

